class NumberProcessor {
private:
std::vector<int> numbers;

public:
/ * *
@description Add numbers to the collection
"?" @param num - The number to be added
"!" @return void
* /
void addNumber(int num) {
numbers.push_back(num);
}

/ * *
@description Calculate the sum of all the numbers
"!" @return int Sum of digits
* /
int getSum() const {
return std::accumulate(numbers.begin(), numbers.end(), 0);
}

/ * *
@description Calculate the average value of the numbers
"!" @return double mean
* /
double getAverage() const {
return numbers.empty() ? 0 : static_cast<double>(getSum()) / numbers.size();
}
};

