class Utils {
/ * *
* * @description Format the date in Chinese format
"?" @param date - Date Object
"!" @return string The formatted date string
* /
static formatDate(date) {
return new Intl.DateTimeFormat('zh-CN').format(date)
}

/ * *
@description anti-shake function, delayed execution
"?" @param func - The function to be debunked
"?" @param wait - Delay Time (milliseconds)
"!" @return Function Function after debouncing
* /
static debounce(func, wait) {
let timeout
return function executedFunction(... args) {
const later = () => {
clearTimeout(timeout)
func(... args)
}
clearTimeout(timeout)
timeout = setTimeout(later, wait)
}
}

/ * *
@description Deep clone object
"?" @param obj - Object to be cloned
"!" @return any cloned object
* /
static deepClone(obj) {
if (obj === null || typeof obj ! == 'object') return obj
if (obj instanceof Date) return new Date(obj)
if (obj instanceof Array) return obj.map(item => Utils.deepClone(item))

const cloned = {}
for (const key in obj) {
if (obj.hasOwnProperty(key)) {
cloned[key] = Utils.deepClone(obj[key])
}
}
return cloned
}
}

export default Utils
